#include <stdio.h>

struct node {
    int v;
    struct node* prev;
    struct node* next;
};

int main() {
    struct node a = {1, NULL, NULL};
    struct node b = {2, NULL, NULL};
    struct node c = {3, NULL, NULL};

    a.next = &b; b.prev = &a;
    b.next = &c; c.prev = &b;

    struct node* tail = &c;
    printf("%d %d %d", tail->v, tail->prev->v, tail->prev->prev->v);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int trace_sum(int* mat, int n) {
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += *(mat + i * n + i);
    }
    return sum;
}

int main() {
    int n = 3;
    int* mat = (int*)malloc(sizeof(int) * n * n);
    for (int i = 0; i < n * n; i++) {
        mat[i] = i + 1;
    }
    int result = trace_sum(mat, n);
    free(mat);
    printf("%d", result);
    return 0;
}
